    private int execDML(String sql) throws Exception {
        PreparedStatement pstmt = null;


        DBTransaction db = null;
        try {

            db = this.getDBTransaction();

            System.err.println("Updated Query is:" + sql);

            pstmt = db.createPreparedStatement(sql, 0);
            return pstmt.executeUpdate();
        } catch (Exception exception) {
            throw exception;
        } finally {
            pstmt.close();

        }
    }

