    public BigDecimal dublicateCourtBcHearingReservation(Row previousReservation, BigDecimal hearingDate, BigDecimal id,
                                                         BigDecimal reservationId) {
        ViewObject CourtBcHearingReservationVO = this.getCourtBcHearingReservationDelayVO1();
        Row CourtBcHearingReservationROW = CourtBcHearingReservationVO.createRow();
        CourtBcHearingReservationROW.setAttribute("Id", id);
        CourtBcHearingReservationROW.setAttribute("ReservationId", reservationId);
        CourtBcHearingReservationROW.setAttribute("BusinessCaseId", previousReservation.getAttribute("BusinessCaseId"));
        CourtBcHearingReservationROW.setAttribute("OrigEntity", previousReservation.getAttribute("OrigEntity"));
        CourtBcHearingReservationROW.setAttribute("CircleHearingDateId", hearingDate);
        CourtBcHearingReservationVO.insertRow(CourtBcHearingReservationROW);
        return (BigDecimal) CourtBcHearingReservationVO.getCurrentRow().getAttribute("Id");
    }

    public void dublicateResParties(ViewObject resePariesVO, BigDecimal reservationId) {

        System.err.println("reservationId  >>  " + reservationId);
        RowSetIterator rws = resePariesVO.createRowSetIterator(null);
        while (rws.hasNext()) {
            Row resPartyRow = rws.next();
            System.err.println("resPartyRow.getAttribute   " + resPartyRow.getAttribute("UnspecializedFlag"));
            BigDecimal spec = (BigDecimal) resPartyRow.getAttribute("UnspecializedFlag");
            if (null == spec || spec.compareTo(new BigDecimal(0)) == 0) {
                resPartyRow.setAttribute("Postponed", new BigDecimal(1));
                ViewObject CourtBcHearingResPartiesVO = this.getCourtBcHearingResPartiesDelayVO1();
                Row CourtBcHearingResPartiesROW = CourtBcHearingResPartiesVO.createRow();
                CourtBcHearingResPartiesROW.setAttribute("PartyId", resPartyRow.getAttribute("PartyId"));
                CourtBcHearingResPartiesROW.setAttribute("PartyOrder", resPartyRow.getAttribute("PartyOrder"));

                CourtBcHearingResPartiesROW.setAttribute("BcDegreeSpecId", resPartyRow.getAttribute("BcDegreeSpecId"));
                CourtBcHearingResPartiesROW.setAttribute("CourtBcHearingResId", reservationId);
                CourtBcHearingResPartiesROW.setAttribute("PreviousReservationId",
                                                         resPartyRow.getAttribute("CourtBcHearingResId"));
                CourtBcHearingResPartiesROW.setAttribute("UpdateBy", "Postponed");
                CourtBcHearingResPartiesVO.insertRow(CourtBcHearingResPartiesROW);
                //  getCounting().add(new BigDecimal(1));
            }
        }
    }

