            db = this.getDBTransaction();
            String sql =
                "SELECT  SEQ FROM  BUSINESS_CASE_DETAILS  bc inner join BUSINESS_CASE_LEDGER_SEQ se  on  se.BUSINESS_CASE_DETAILS_ID = bc.ID where bc.CASE_SCHEMA_ID=" +
                CASE_SCHEMA_ID + " and SEQ =" + seq + " and YEAR=" + year + " and se.ENTITY_ID =" + entityId + " and se.LEDGER_ID = "+ledgerId;
            System.err.println("==============> getStoclLoc-sql" + sql);
            stat = db.createPreparedStatement(sql, 1);

