    public Number getMaxFieldValue(String tableName, String columnName) {
        int maxVal = 0;
        PreparedStatement pstmt = null;
        ResultSet rs = null;
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            String sql = "SELECT NVL(MAX(TO_NUMBER(" + columnName + ")), 0)+1 AS MAX_VAL" + " FROM " + tableName;
            pstmt = db.createPreparedStatement(sql, db.DEFAULT);

            rs = pstmt.executeQuery();
            while (rs.next()) {
                maxVal = rs.getInt("MAX_VAL");
            }
        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            try {
                rs.close();
                pstmt.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        return new Number(maxVal);
    }

    public void newFolderDataWitness(BigDecimal courtBcHearingResPartiesID, String Partyname, int partyOrder,
                                     BigDecimal unspecializedFlag) {
        Integer years = (Integer) ADFContext.getCurrent().getSessionScope().get("PPYEAR");
        System.out.println(years + "*************---" + ADFContext.getCurrent().getSessionScope().get("PPYEAR"));
        int type = 0;
        // baraa
        if (unspecializedFlag.compareTo(new BigDecimal(5)) == 0)
            type = 7;
        // tasalhaa
        if (unspecializedFlag.compareTo(new BigDecimal(3)) == 0)
            type = 10;
        // adam igtsasa
        if (unspecializedFlag.compareTo(new BigDecimal(1)) == 0 || unspecializedFlag.compareTo(new BigDecimal(12)) == 0)
            type = 9;
        if (unspecializedFlag.compareTo(new BigDecimal(2)) == 0)
            type = 32;
        if (unspecializedFlag.compareTo(new BigDecimal(4)) == 0)
            type = 33;

        int year = Calendar.getInstance().get(Calendar.YEAR);
        RowSet folderRowSet = this.getExcFolderDataVO1();
        Number fieldValue =  new Number(100);
        if (years<2023)
          fieldValue = this.getMaxFieldValue("EXC_FOLDER_DATA where FOLDER_TYPE =" + type+" and  Police_Station_Entity_Id = "+ADFContext.getCurrent().getSessionScope().get("OrigEntity")+ " and year = 2020", "SEQUENCE_NUMBER");
        System.err.println(partyOrder + "    ---*****fieldValue  is --------------------    " + fieldValue);

        fieldValue = fieldValue.add(partyOrder);


        System.out.println("2020 fieldValue  is --------------------    " + fieldValue);
        Row folderROW = folderRowSet.createRow();
        folderROW.setAttribute("ResPartyId", courtBcHearingResPartiesID);
       
        if (years == 0)
            folderROW.setAttribute("Year", new BigDecimal(2020));
        else
            folderROW.setAttribute("Year", new BigDecimal(2020));
        if (years>2022)
            folderROW.setAttribute("Year", new BigDecimal(1900));
//        folderROW.setAttribute("FolderType", new BigDecimal(type));
        folderROW.setAttribute("FolderType", new BigDecimal(type));
        folderROW.setAttribute("SequenceNumber", fieldValue);
        folderROW.setAttribute("sequenceFold", fieldValue);
        folderROW.setAttribute("PartyName", Partyname);
        folderROW.setAttribute("GuiltlessnessFlag", "Y");
        folderRowSet.insertRow(folderROW);
    }

