    public BigDecimal removeRow(String viewObject, String column, BigDecimal val) {
        BigDecimal ID = BigDecimal.ZERO;
        ViewObject vo = this.findViewObject(viewObject);
        System.out.println(viewObject + "VO Count " + vo.getRowCount());
        RowSetIterator rws = vo.createRowSetIterator(null);
        while (rws.hasNext()) {
            Row rw = rws.next();

            BigDecimal id = (BigDecimal) rw.getAttribute(column);
            System.out.println("^^^" + id + "****" + val);
            if (id.compareTo(val) == 0) {
                ID = (BigDecimal) rw.getAttribute("Id");

                //                System.out.println(rw);
                //                rw.remove();
                rw.setAttribute("DeletedFlag", "Y");
                System.out.println("Removed  >>" + ID);
            }
        }
        return ID;
    }


    public BigDecimal markDeleteRow(String viewObject, String column, BigDecimal val) {
        BigDecimal ID = BigDecimal.ZERO;
        ViewObject vo = this.findViewObject(viewObject);
        System.out.println(viewObject + "VO Count " + vo.getRowCount());
        RowSetIterator rws = vo.createRowSetIterator(null);
        while (rws.hasNext()) {
            Row rw = rws.next();
            ID = (BigDecimal) rw.getAttribute("Id");
            BigDecimal id = (BigDecimal) rw.getAttribute(column);
            System.out.println("^^^" + id + "****" + val);
            if (id.compareTo(val) == 0) {
                System.err.println("//////////");
                System.out.println(rw);
                //                rw.setAttribute("DeleteFlag", "Y");
                rw.remove();
                System.err.println("//////////");
                //                    System.out.println(rw);
            }
        }
        return ID;
    }

