    public String getPreviousPaidAmount(String party_id, String folderType  ){
            String result="";
            String sql =  "select nvl (claim_total, 0)   ||','|| id from exc_claims where CLAIM_FOLDER_ID = "+folderType+" and PARTY_ID = '"+party_id+"' and deleted_flag = 'N'" ;
            Object val = getDataAsObjectFromQuery(sql);
            if(val == null)
                return 0+","+0;
            else 
                result = val+"";
            
            return result;
                
            }
    
