    public String ValidateSettlementPenalty(String number, String folderType,
                                            String  Year ,String entity ,String  nationalID ){
            String result="";
            String sql = "select nvl ( CLAIM_TOTAL , 0 ) ||','|| id from EXC_CLAIMS where CLAIM_NUMBER = "+number+" and CLAIM_YEAR = "+Year+" and CLAIM_POLICE_STATION_ID =  "+entity+ "and CLAIM_FOLDER_ID="+folderType 
                         + " and ID_NUMBER = '"+nationalID+"'"
                ;
            
            Object val = getDataAsObjectFromQuery(sql);
            if(val == null)
                return 0+","+0+","+0;
            else {
                result = val+"";
                String[] split = result.split(",");
                if (split.length > 0) {
                     BigDecimal   claimId =new BigDecimal ( split[1]) ;
                String sql2 ="select sum (SETTLEMENT_AMOUNT ) from EXC_SETTLEMENT_PENALTY where DELETED_FALG ='N' and CLAIM_ID_SOURCE = "+claimId;
                Object val2 = getDataAsObjectFromQuery(sql2);
                if(val2 == null)
                   result=result+","+0;
                else
                result=result+","+val2;
            }
            }
            
            
            return result;
        }
    
    public String ValidatePoliceGurantee(BigDecimal PoliceNo, BigDecimal BusinessCaseType,
                                         BigDecimal ParYear, BigDecimal OrigEntity ,String idNumber)
    {
        
        String result="";
            if (PoliceNo != null && BusinessCaseType != null && ParYear != null && OrigEntity != null) {
                String Column = "PoliceNumber,BusinessCaseType,OriginEntity,ParYear";
                String Value = "" + PoliceNo + "," + BusinessCaseType + "," + OrigEntity + "," + ParYear;
                
                ViewObject ParPoliceAuthorityReportVO = filterByViewCriteria("ParPoliceAuthorityReportVO2", Column, Value);
                int rowCount = ParPoliceAuthorityReportVO.getRowCount();
                System.out.println("rowCount is "+rowCount);
                if (rowCount > 0) {
                    Row ParPoliceAuthorityReportRW = ParPoliceAuthorityReportVO.createRowSetIterator(null).next();
                    BigDecimal BusinessCaseId = (BigDecimal) ParPoliceAuthorityReportRW.getAttribute("BusinessCaseId");
                 
                    String sql = "SELECT nvl(EXC_FOLDER_PROCEDURES.id , 0 ) ||','|| nvl(ADVANCE_PAYMENT_AMOUNT,0) ||','|| nvl(number_paid,0) FROM EXC_FOLDER_PROCEDURES where FEES_TYPE_ID = 4 and ID in (SELECT PROCEDURE_ID FROM EXC_FOLDER_ACTIONS where FOLDER_RECORD_ID in (SELECT id FROM EXC_FOLDER_DATA where RES_PARTY_ID in (SELECT COURT_BC_HEARING_RES_PARTIES.id FROM COURT_BC_HEARING_RES_PARTIES inner join par_parties on par_parties.id =COURT_BC_HEARING_RES_PARTIES.party_id  where par_parties.id_number ='"+idNumber+"' and COURT_BC_HEARING_RES_ID  in (SELECT id FROM COURT_BC_HEARING_RESERVATION where BUSINESS_CASE_id = "+BusinessCaseId+" ) ) ))";
                    
                    Object val = getDataAsObjectFromQuery(sql);
                    
                    result = val+"";
                    String[] split = result.split(",");
                    if (split.length > 1) {
                         BigDecimal   procId =new BigDecimal ( split[0]) ;
                        if(procId.compareTo(new BigDecimal(0))==1)
                        {
                                String sql2 =  "select sum ( SETTLEMENT_AMOUNT ) from EXC_PROCEDURE_CLAIM_FOLDER where DELETED_FALG = 'N' and FOLDER_PROCEDURE_ID = " +procId;
                                Object val2 = getDataAsObjectFromQuery(sql2);
                                if(val2 == null)
                                    result=result+","+0;
                                else
                                result=result+","+val2;
                            }
                    }
                }
            }
        return result ;
        }

