            BigDecimal formCaseDescriptionId = (BigDecimal) rws2.next().getAttribute("FormCaseDescriptionId");
            BigDecimal Hearing_Reservaion_ID = newCourtBcProsectionHearingReservation(businessCaseId, OrigEntity);
