    public BigDecimal New_BUSINESS_CASE(BigDecimal PoliceNo, BigDecimal BusinessCaseType, BigDecimal OrigEntity) {

        ViewObject BusinessCaseVO = this.getBusinessCase1();
        Row BusinessCaseROW = BusinessCaseVO.createRow();

        BusinessCaseROW.setAttribute("CaseNumber", PoliceNo);
        BusinessCaseROW.setAttribute("EntityId", OrigEntity);
        BusinessCaseROW.setAttribute("CaseType", BusinessCaseType);
        BusinessCaseROW.setAttribute("BusinessCaseType", BusinessCaseType);
        if (BusinessCaseType.compareTo(new BigDecimal(12)) == 0)
            BusinessCaseROW.setAttribute("JournalistFlag", new BigDecimal(1));
        BusinessCaseVO.insertRow(BusinessCaseROW);

        return (BigDecimal) BusinessCaseVO.getCurrentRow().getAttribute("Id");
    }


    public BigDecimal New_Police_Report(BigDecimal BC_ID, BigDecimal PoliceNo, BigDecimal BusinessCaseType,
                                        BigDecimal ParYear, BigDecimal OrigEntity, String entityGozyaa) {
       
       
       
       
       
       String sql = "select parent_entity_id from entity  where id ="+OrigEntity;
        Object obj = getDataAsObjectFromQuery(sql);
        System.err.println("obj   is " + obj);
        if (obj != null)
            entityGozyaa  = obj.toString();
        ViewObject ParPoliceAuthorityReportVO = this.getParPoliceAuthorityReportVO1();
        Row ParPoliceAuthorityReportROW = ParPoliceAuthorityReportVO.createRow();
        SimpleDateFormat sdformat = new SimpleDateFormat("yyyy-MM-dd");
        Date d = new Date();
        try {
            d = sdformat.parse("1000-01-01");
        } catch (ParseException e) {
        }
        ParPoliceAuthorityReportROW.setAttribute("ReceivedDate", d);
        ParPoliceAuthorityReportROW.setAttribute("BusinessCaseId", BC_ID);
        ParPoliceAuthorityReportROW.setAttribute("PoliceNumber", PoliceNo);
        if (entityGozyaa != null)
            ParPoliceAuthorityReportROW.setAttribute("EntityId", new BigDecimal(entityGozyaa));
        else
            ParPoliceAuthorityReportROW.setAttribute("EntityId", OrigEntity);
        ParPoliceAuthorityReportROW.setAttribute("BusinessCaseType", BusinessCaseType);
        ParPoliceAuthorityReportROW.setAttribute("ParYear", ParYear);
        ParPoliceAuthorityReportROW.setAttribute("OriginEntity", OrigEntity);
        ParPoliceAuthorityReportVO.insertRow(ParPoliceAuthorityReportROW);
        BigDecimal policeId = (BigDecimal) ParPoliceAuthorityReportVO.getCurrentRow().getAttribute("Id");
        
        {
                ViewObject ParPoliceAuthorityReportLogVO = this.getParPoliceAuthorityLogVO1();
                Row ParPoliceAuthorityReportLogROW = ParPoliceAuthorityReportLogVO.createRow();
                ParPoliceAuthorityReportLogROW.setAttribute("BusinessCaseId", BC_ID);
                ParPoliceAuthorityReportLogROW.setAttribute("PoliceNumber", PoliceNo);
                if (entityGozyaa != null)
                    ParPoliceAuthorityReportLogROW.setAttribute("EntityId", new BigDecimal(entityGozyaa));
                else
                    ParPoliceAuthorityReportLogROW.setAttribute("EntityId", OrigEntity);
                ParPoliceAuthorityReportLogROW.setAttribute("BusinessCaseType", BusinessCaseType);
                ParPoliceAuthorityReportLogROW.setAttribute("ParYear", ParYear);
                ParPoliceAuthorityReportLogROW.setAttribute("OriginEntity", OrigEntity); 
                ParPoliceAuthorityReportLogROW.setAttribute("ParId", policeId);
                ParPoliceAuthorityReportLogVO.insertRow(ParPoliceAuthorityReportLogROW);
            }
        
        return policeId;
    }

