    public BigDecimal New_Court_BC_Session_Judgment(BigDecimal Hearing_Reservaion_ID) {
   ViewObject vo = filterByViewCriteria("ExcCourtBcSessionJudgmentVO1", "CourtBcHearingResId", ""+Hearing_Reservaion_ID);
        RowSetIterator rws= vo.createRowSetIterator(null);
        if (!rws.hasNext()){
        ViewObject ExcCourtBcSessionJudgmentVO = this.getExcCourtBcSessionJudgmentVO1();
       
        Row ExcCourtBcSessionJudgmentROW = ExcCourtBcSessionJudgmentVO.createRow();
        ExcCourtBcSessionJudgmentROW.setAttribute("CourtBcHearingResId", Hearing_Reservaion_ID);
        ExcCourtBcSessionJudgmentROW.setAttribute("ClassifiedFlag", new BigDecimal(1));
        Boolean flag = false;
        if (ADFContext.getCurrent().getSessionScope().get("ProsecutionCJ") != null)
            flag = (Boolean) ADFContext.getCurrent().getSessionScope().get("ProsecutionCJ");
        if (flag) {
            ExcCourtBcSessionJudgmentROW.setAttribute("JudgmentType", new BigDecimal(3));
        }
        //        else
        //            ExcCourtBcSessionJudgmentROW.setAttribute("JudgmentType", new BigDecimal(1));
        ExcCourtBcSessionJudgmentVO.insertRow(ExcCourtBcSessionJudgmentROW);
        return (BigDecimal) ExcCourtBcSessionJudgmentVO.getCurrentRow().getAttribute("Id");
        }
        else
        return (BigDecimal) rws.next().getAttribute("Id");
    }


