    public void New_BC(BigDecimal PoliceNo, BigDecimal BusinessCaseType, BigDecimal ParYear, BigDecimal OrigEntity,
                       BigDecimal BusinessCaseDegree, String entityGozyaa) {
        try {
            BigDecimal BC_ID = New_BUSINESS_CASE(PoliceNo, BusinessCaseType, OrigEntity);
            //  00
            filterByViewCriteria("BusinessCaseDetailsVO1", "BusinessCaseId", "" + BC_ID);
            BigDecimal Police_ID =
                New_Police_Report(BC_ID, PoliceNo, BusinessCaseType, ParYear, OrigEntity, entityGozyaa);

            Row rw = this.getValidatePoliceReportROVO1().getCurrentRow();
            rw.setAttribute("BussinesId", BC_ID);
            rw.setAttribute("PoliceId", Police_ID);

            ADFContext.getCurrent().getSessionScope().put("BC_ID", BC_ID);
            ADFContext.getCurrent().getSessionScope().put("Police_ID", Police_ID);
            ADFContext.getCurrent().getSessionScope().put("Police_No", PoliceNo);
            BigDecimal Hearing_Reservaion_ID = New_Court_BC_Hearing_Reservation(BC_ID, OrigEntity, BusinessCaseDegree);
            BigDecimal Form_Case_Description_ID = New_Form_Case_Decision(BC_ID);
            System.out.println("Form_Case_Description_ID " + Form_Case_Description_ID);
            System.out.println("Hearing_Reservaion_ID " + Hearing_Reservaion_ID);
            BigDecimal SessionJ_udgment_ID = New_Court_BC_Session_Judgment(Hearing_Reservaion_ID);
            BigDecimal Exc_Court_BC_Decision_ID = New_Court_BC_Decision(SessionJ_udgment_ID);

            // BUSINESS CASE
            newBusinessCaseDetails(BC_ID, BigDecimal.ONE,
                                   "id=" + Police_ID + "&businessCaseId=" + BC_ID + "&crudMethod=update",
                                   "\u0627\u0644\u0642\u0636\u064a\u0647", entityGozyaa);

            // POLICE REPORT
            newBusinessCaseDetails(BC_ID, new BigDecimal(2568),
                                   "id=" + Police_ID + "&businessCaseId=" + BC_ID + "&crudMethod=update",
                                   "\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u062d\u0636\u0631",
                                   entityGozyaa);

            // QIED & WASF
            newBusinessCaseDetails(BC_ID, new BigDecimal(2788), "businessCaseId=" + BC_ID,
                                   "\u0642\u064a\u062f \u0648 \u0648\u0635\u0641", entityGozyaa);

            //        addNewconvicted_1_1(  Form_Case_Description_ID,   Exc_Court_BC_Decision_ID,
            //                                              Police_ID) ;


            Row rw2 = this.getValidatePoliceReportROVO1().getCurrentRow();
            rw2.setAttribute("BussinesId", BC_ID);
            rw2.setAttribute("PoliceId", Police_ID);

            nwBusinessCaseLogStatus(new BigDecimal(entityGozyaa), BC_ID, BusinessCaseType);

        } catch (Exception e) {
            e.printStackTrace();
        }

    }


