    public String[] getLawyerData(long partyId) {
        String[] data = new String[3];

        String sql = "SELECT MAX(ID) " + "FROM  PAR_LAWYER_PARTIES " + "WHERE PARTY_ID = ? ";

        PreparedStatement ps = null;
        ResultSet rs = null;
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setLong(1, partyId);
            rs = ps.executeQuery();

            if (rs.next()) {
                long id = rs.getLong(1);

                sql =
                    "SELECT PRIMARY_LAWER.ID , PRIMARY_LAWER.RETAINER_NUMBER , PRIMARY_LAWER.NAME " +
                    " FROM PAR_LAWYER_PARTIES LAW_PART , PAR_LAWYERS PRIMARY_LAWER " +
                    " WHERE LAW_PART.LAWYER_ID = PRIMARY_LAWER.ID " + " AND LAW_PART.ID = ? ";

                ps = db.createPreparedStatement(sql, 0);
                ps.setLong(1, id);
                rs = ps.executeQuery();
                if (rs.next()) {
                    data[0] = rs.getString(1);
                    data[1] = rs.getString(2);
                    data[2] = rs.getString(3);
                }
            }

        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return data;
    }

