    public int validateActionClosed(int folderId) {
        int closed = 0;
        PreparedStatement ps = null;
        ResultSet rs = null;
        String sql =
            "SELECT COUNT(FOLDER.ID) " + " FROM EXC_FOLDER_DATA FOLDER , EXC_FOLDER_ACTIONS ACTIONS " +
            " WHERE FOLDER.ID = ACTIONS.FOLDER_RECORD_ID " + " AND FOLDER.ID = ? " + " AND ACTIONS.CLOSED_FLAG = 1";


        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setInt(1, folderId);
            rs = ps.executeQuery();
            if (rs.next()) {
                closed = rs.getInt(1);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return closed;
    }
    public BigDecimal getHearingDateIdd2(BigDecimal entityId, String hearingDate, BigDecimal bcDegree) {
      
        
        BigDecimal closed = new BigDecimal(0);
        System.err.println("TYPES  " + ADFContext.getCurrent().getSessionScope().get("BusinessCaseType"));
        BigDecimal BusinessCaseType =new BigDecimal(3) ;
        if(ADFContext.getCurrent().getSessionScope().get("BusinessCaseType") != null)
            BusinessCaseType = new BigDecimal(ADFContext.getCurrent().getSessionScope().get("BusinessCaseType") + "");
        String sql = "";
        sql =
            "SELECT NVL (ID, 0)" + "id FROM COURT_CIRCLES_DATES_HEARING WHERE ENTITY_ID in " +
            "(select id from entity where parent_entity_id in (select court_id from entity where id =  " +
            entityId + ")) " + "AND to_date( HEARING_DATE ) = TO_date ('" + hearingDate +
            "', 'yyyy-mm-dd')  AND BC_DEGREE_ID = " + bcDegree;

        if (BusinessCaseType.compareTo(new BigDecimal(16)) == 0) {
            bcDegree = new BigDecimal(3);
        }
        Boolean GnayaatFlag = false;
        if(ADFContext.getCurrent().getSessionScope().get("GnayaatFlag") != null)
           GnayaatFlag = (Boolean) ADFContext.getCurrent().getSessionScope().get("GnayaatFlag");
        if(GnayaatFlag)
         entityId = new BigDecimal(ADFContext.getCurrent().getSessionScope().get("NeyabaaGozayaa").toString());
        System.out.println("GnayaatFlag   new   is   "+GnayaatFlag);
        if (bcDegree.compareTo(new BigDecimal(3)) == 0 || bcDegree.compareTo(new BigDecimal(4)) == 0 ||
            BusinessCaseType.compareTo(new BigDecimal(16)) == 0 || GnayaatFlag)
            sql =
                "SELECT NVL (ID, 0)" + "id FROM COURT_CIRCLES_DATES_HEARING WHERE ENTITY_ID in " +

                "(SELECT DESTINATION_ENTITY_ID FROM ENTITY_CIRCLES WHERE SOURCE_ENTITY_ID = " +entityId+
             // "in (SELECT PARENT_ENTITY_ID FROM ENTITY WHERE ENTITY.ID =" + entityId + "and join_type = 1) " +
              ") AND to_date( HEARING_DATE ) = TO_date ('" + hearingDate + "', 'yyyy-mm-dd')  AND BC_DEGREE_ID = " +
              bcDegree;

 

        Object obj = getDataAsObjectFromQuery(sql);
        System.err.println("obj   is " + obj);
        if (obj != null)
            closed = new BigDecimal(obj.toString());
        
        
        
        
        if (closed.compareTo(new BigDecimal(0)) == 0) {
           
            ViewObject courtCirclesDatesHearingVO = this.getCourtCirclesDatesHearing1();
            Row row = courtCirclesDatesHearingVO.createRow();
            row.setAttribute("Capacity", new BigDecimal(500));
          
                row.setAttribute("EntityId", entityId);
            

            row.setAttribute("HearingDate", hearingDate);
         
                row.setAttribute("BcDegreeId", bcDegree);
            
                row.setAttribute("Source", "GONA7AA_"+bcDegree);

            
            
            courtCirclesDatesHearingVO.insertRow(row);

          Row  currentRow = courtCirclesDatesHearingVO.getCurrentRow();
            closed = (BigDecimal) currentRow.getAttribute("Id");
            
            System.out.println("$$$$$$$$getDateId"+closed);  
            this.getDBTransaction().commit();
        }

        return closed;
    }
    
    
