    public boolean checkNTRAResultsIsTrue(String nationalId , String mobileNo){
        
            int count = 0;
            boolean check = false;
            String sql = "SELECT count(*)\n" + 
                         "FROM exc_ntra_inquiry_results\n" + 
                         "where national_id = '"+nationalId+"'\n" + 
                         "and mobile_no = '"+mobileNo+"'\n" +
                         "and verfication_result = 'T'";

            PreparedStatement ps = null;
            ResultSet rs = null;

            DBTransaction db = null;
            try {
                db = this.getDBTransaction();
                ps = db.createPreparedStatement(sql, 0);
//                ps.setBigDecimal(1, resId);
                rs = ps.executeQuery();
                if (rs.next()) {
                    count = rs.getInt(1);
                    if (count > 0 ){
                        check = true; 
                    }
                }

            } catch (Exception e) {
                e.printStackTrace();
            } finally {
                try {
                    rs.close();
                    ps.close();

                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
            return check;
        }

