    private int validateSentToCourt(BigDecimal resId) {

        int count = 0;

        String sql =
            "SELECT COUNT(RES.ID) FROM COURT_BC_HEARING_RESERVATION RES WHERE RES.ID = ? AND RES.SENT_TO_COURT = 'Y'";

        PreparedStatement ps = null;
        ResultSet rs = null;

        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setBigDecimal(1, resId);
            rs = ps.executeQuery();
            if (rs.next()) {
                count = rs.getInt(1);
                if (count > 0) {
                    sql = "UPDATE COURT_BC_HEARING_RESERVATION RES SET RES.SENT_TO_COURT = 'A' WHERE RES.ID = ? ";
                    ps = db.createPreparedStatement(sql, 0);
                    ps.setBigDecimal(1, resId);
                    ps.executeUpdate();
                }
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return count;
    }


