    private BigDecimal getLastReservationIDProcedure(Object businessCaseId, Object partyId) {
        String sql =
            "SELECT  max(RES.ID)  RESERVATION_ID\n" +
            "       from COURT_BC_HEARING_RESERVATION RES ,COURT_BC_HEARING_RES_PARTIES RES_PART,EXC_FOLDER_PROCEDURES proc,EXC_FOLDER_ACTIONS ACTS\n" +
            "       where \n" + "        RES_PART.COURT_BC_HEARING_RES_ID = res.id\n" +
            "       and RES_PART.id = PROC.RES_PARTY_ID(+)\n" + "       and proc.id = ACTS.PROCEDURE_ID (+)\n" +
            "       and RES.business_case_id = " + businessCaseId + "\n" + "       and RES_PART.party_id = " + partyId +
            "\n" + "       and ACTS.ACTION_TYPE in (1, 2, 8, 9, 23, 24, 14 , 149 ,156, 150 , 151,153,154,155 , 168)\n" + "       order by RES.id desc";
        Object ob = getDataAsObjectFromQuery(sql);
        if (ob == null)
            return new BigDecimal(0);

        return new BigDecimal(ob.toString());
    }

    public int getEntityIdFromBusinseCase(long bcid) {
        String sql =
            "SELECT ENT.PARENT_ENTITY_ID   FROM entity Ent, PAR_POLICE_AUTHORITY_REPORT par  WHERE par.BUSINESS_CASE_ID = " +
            bcid + " and PAR.ORIGIN_ENTITY = ENT.ID";
        Object value = getDataAsObjectFromQuery(sql);
        return value == null ? 0 : Integer.parseInt(value.toString());
    }

