    public Integer findNotarization( String retainerSerial , String harf , String year , String OfficeId , String Type ){
        
           String typeName = getOfficeName(Type);
            Object DegId =
                getDataAsObjectFromQuery("SELECT nvl(max( LAWER_ID),-1) FROM  NOTARIZATION_RETAINER_DATA where RETAINER_SERAIL ='"+retainerSerial+"' and HARF ='"+harf+ 
                "' and YEAR ='"+year+"' and OFFICE_ID ="+OfficeId+" and TRANSACTIONCATEGORYDESC='"+typeName+"'");
           return Integer.parseInt(DegId.toString());
        }
    
