    public BigDecimal getGanyaatDateId(BigDecimal entityId, Date hearingDate, int deg) {
        BigDecimal bcDegree = new BigDecimal(0);
      if (deg == 0)
           bcDegree = new BigDecimal(8) ;
         else
               bcDegree = new BigDecimal(deg) ;
        BigDecimal hearingDateId =  new BigDecimal(0) ;
            try{
          hearingDateId = getHearingDateId2(entityId, hearingDate, bcDegree);
     
                        if (hearingDateId.compareTo(new BigDecimal(0)) == 0) {
                            System.out.println("$$$$$$$$getGanyaatDateId");
                            ViewObject courtCirclesDatesHearingVO = this.getCourtCirclesDatesHearing1();
                            Row row = courtCirclesDatesHearingVO.createRow();
                            row.setAttribute("Capacity", new BigDecimal(500));
                          
                                row.setAttribute("EntityId", entityId);
                            

                            row.setAttribute("HearingDate", hearingDate);
                         
                                row.setAttribute("BcDegreeId", bcDegree);
                            
                                row.setAttribute("Source", "GONA7AA_"+bcDegree);

                            
                            
                            courtCirclesDatesHearingVO.insertRow(row);

                          Row  currentRow = courtCirclesDatesHearingVO.getCurrentRow();
                            hearingDateId = (BigDecimal) currentRow.getAttribute("Id");
                            
                            
                        }
                    
        } catch (Exception e) {
            e.printStackTrace();
        }
        return hearingDateId;
    }
    


