    public BigDecimal getPenaltyAmount(String respartyId) {
        String sql =
            "(SELECT NVL (SUM (DECISIONS.PENALTY_AMOUNT), 0)" + "   FROM EXC_COURT_BC_CHARGES_PARTIES PARTIES," +
            "  EXC_COURT_BC_CHARGE_DECISIONS DECISIONS" + " WHERE     PARTIES.CHARGE_DECISION_ID = DECISIONS.ID " +
            " AND PARTIES.RES_PARTY_ID = " + respartyId + ") ";
        return new BigDecimal(getDataAsObjectFromQuery(sql) + "");
    }

