    public String getPunshment(String respartyId) {
        String sql =
            "(SELECT    DECISIONS.IMPRISONMENT_YEARS\n" + "                               || ','\n" +
            "                               || DECISIONS.IMPRISONMENT_MONTHS\n" +
            "                               || ','\n" +
            "                               || DECISIONS.IMPRISONMENT_DAYS\n" +
            "                               || ','\n" +
            "                               || DECISIONS.GURANTEE_AMOUNT\n" +
            "                               || ','\n" +
            "                               || DECISIONS.WORK_AMOUNT_FLAG\n" +
            "                               || ','\n" + "                               || DECISIONS.WORK_AMOUNT\n" +
            "                               || ','\n" +
            "                               || DECISIONS.PENALTY_DUE_DATE \n" +
            "                               || ','\n" +
            "                               || DECISIONS.PENALTY_AMOUNT_FIXED_FLAG\n" +
            "                               || ','\n" + "                               || DECISIONS.PENALTY_AMOUNT\n" +
            "                               || ','\n" + "                               || DECISIONS.ID\n" +
            "                               || ','\n" +
            "                               || PARTIES.Id || ',' || DECISIONS.PENALTY_END_DATE\n" +
            "                          FROM EXC_COURT_BC_CHARGES_PARTIES PARTIES,\n" +
            "                               EXC_COURT_BC_CHARGE_DECISIONS DECISIONS\n" +
            "                         WHERE     PARTIES.CHARGE_DECISION_ID = DECISIONS.ID\n" +
            "                               AND PARTIES.RES_PARTY_ID = " + respartyId + "\n" +
            "                               AND ROWNUM = 1)";
        return getDataAsObjectFromQuery(sql) + "";
    }

    public BigDecimal getReservationId(long businessCaseId, long hearingDateId, int degree) {
        BigDecimal id = null;
        String sql =
            "SELECT MAX(RES.ID) " + " FROM COURT_BC_HEARING_RESERVATION RES , COURT_BC_HEARING_RES_PARTIES RES_PAR " +
            " WHERE RES_PAR.COURT_BC_HEARING_RES_ID = RES.ID " + " AND RES.BUSINESS_CASE_ID = ? " +
            " AND RES_PAR.BC_DEGREE_SPEC_ID = ? " + " AND RES.CIRCLE_HEARING_DATE_ID = ? ";

        PreparedStatement ps = null;
        ResultSet rs = null;

        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setLong(1, businessCaseId);
            ps.setInt(2, degree);
            ps.setLong(3, hearingDateId);

            rs = ps.executeQuery();
            if (rs.next()) {
                id = rs.getBigDecimal(1);
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return id;
    }

