    private Object nvl(Object val) {
        if (val == null || "".equalsIgnoreCase(val + ""))
            return 0;
        else
            return val;
    }

    private Object nvl(Object val, Object value) {
        if (val == null || "".equalsIgnoreCase(val + ""))
            return value;
        else
            return val;
    }

    public int validateSequenceNumber(String folderType, String repeatedFlag, String sequenceNumber, String year,
                                      String policenumber) {
        String repFlag = repeatedFlag == null ? "N" : repeatedFlag;
        String sql =
            "SELECT COUNT(ID)\n" + "  FROM EXC_FOLDER_DATA FOLDER\n" + " WHERE     FOLDER.FOLDER_TYPE = " + folderType +
            "\n" + "       AND FOLDER.REPEATED_FLAG = '" + repFlag + "'\n" + "       AND FOLDER.SEQUENCE_NUMBER = " +
            sequenceNumber + "\n" + "       AND FOLDER.YEAR = " + year + " \n" +
            "       AND FOLDER.POLICE_STATION_ENTITY_ID= " + policenumber;
        //        System.err.println(sql);
        return Integer.parseInt(getDataAsObjectFromQuery(sql).toString());
    }

