    private BigDecimal insertIntoExcFolderProcedures(int entityId, BigDecimal resPartyId, int capacityTypeId,
                                                     int userId, long hearingDateId, int actionTypeId,
                                                     String actionDate, String procedureText, double paymentAmount,
                                                     String numberPaid, Object feesTypeId, Object primaryLawyerId , String notes , BigDecimal claimFolderId) {

        ViewObject procedureView = getExcFolderProceduresView1();
        Row procedureRow = procedureView.createRow();

        BigDecimal id = getSequenceValue("EXC_FOLDER_PROCEDURES_SEQ");

        procedureRow.setAttribute("Id", id);
        procedureRow.setAttribute("ProsecutionId", entityId);
        procedureRow.setAttribute("ResPartyId", resPartyId);
        procedureRow.setAttribute("CapacityType", capacityTypeId);
        procedureRow.setAttribute("CreatedBy", userId);
        procedureRow.setAttribute("ProcedureDate", actionDate);
        procedureRow.setAttribute("AdvancePaymentAmount", paymentAmount);
        procedureRow.setAttribute("AdvancePaymentDate", actionDate);
        procedureRow.setAttribute("FeesTypeId", feesTypeId);
        procedureRow.setAttribute("PrimaryLawyerId", primaryLawyerId);
        procedureRow.setAttribute("ActionNotes", notes);
        if ((actionTypeId == 1 || actionTypeId == 2 || actionTypeId == 8 || actionTypeId == 9 || actionTypeId == 14 ||actionTypeId ==168 ||
             actionTypeId == 24  || actionTypeId == 69  || actionTypeId == 68|| actionTypeId == 45 || actionTypeId == 19 || actionTypeId == 18 ||
          actionTypeId == 156  ||  actionTypeId == 149  ||actionTypeId == 150  ||actionTypeId == 151   ||actionTypeId == 153  ||actionTypeId == 154  ||actionTypeId == 155 || actionTypeId == 23) && hearingDateId != 0) {
            procedureRow.setAttribute("CourtCircleDatesHearingId", hearingDateId);
        }

        if (actionTypeId == 1) {
            procedureRow.setAttribute("ProcedureStatus", 14);
        }

        if (actionTypeId == 2) {
            procedureRow.setAttribute("ProcedureStatus", 1);
        }

        if (actionTypeId == 5) {
            procedureRow.setAttribute("ProcedureStatus", 10);
        }

        //    if(actionTypeId == 6)
        //      {
        //	procedureRow.setAttribute("ProcedureStatus", 11);
        //      }

        if (actionTypeId == 7  || actionTypeId == 77) {
            procedureRow.setAttribute("ProcedureStatus", 12);
            procedureRow.setAttribute("NumberPaid", numberPaid);
            if (Integer.parseInt(feesTypeId+"")==3)
            procedureRow.setAttribute("ClaimFolderId", claimFolderId);
        }

        if (actionTypeId == 8) {
            procedureRow.setAttribute("ProcedureStatus", 29);
        }

        if (actionTypeId == 9) {
            procedureRow.setAttribute("ProcedureStatus", 30);
        }

        if (actionTypeId == 10) {
            procedureRow.setAttribute("ProcedureStatus", 22);
        }

        if (actionTypeId == 11) {
            procedureRow.setAttribute("ProcedureStatus", 25);
        }

        if (actionTypeId == 12) {
            procedureRow.setAttribute("ProcedureStatus", 26);
        }

        if (actionTypeId == 13) {
            procedureRow.setAttribute("ProcedureStatus", 24);
        }

        if (actionTypeId == 14 ||actionTypeId ==168) {
            procedureRow.setAttribute("ProcedureStatus", 27);
        }

        if (actionTypeId == 15) {
            procedureRow.setAttribute("ProcedureStatus", 23);
        }

        if (actionTypeId == 16) {
            procedureRow.setAttribute("ProcedureStatus", 28);
        }

        if (procedureText != null) {
            procedureRow.setAttribute("ProcedureText", procedureText);
        }

        procedureView.insertRow(procedureRow);


        return id;
    }


