    public double getTotalOfPaymentValues(BigDecimal resevationId, int typeID) {
        String sql =
            "SELECT NVL (SUM(FEES_AMOUNT), 0) \n" +
            "    FROM (select distinct FEES.FEES_AMOUNT from EXC_COURT_BC_CHARGES_PARTIES PARTIES,\n" +
            "      EXC_COURT_BC_DECISION DECISION,\n" + "      EXC_COURT_BC_DECISION_FEES FEES\n" +
            "    WHERE DECISION.ID                = FEES.DECISION_ID (+)\n" +
            "    AND PARTIES.DECISION_ID          = DECISION.ID\n" + "    AND PARTIES.RES_PARTY_ID         = " +
            resevationId + "\n" + "    AND FEES.FEES_TYPE_ID = " + typeID + ")";
        System.err.println(sql);
        Object val = getDataAsObjectFromQuery(sql);
        double result = val == null ? Double.parseDouble("0") : Double.parseDouble(val + "");
        return result;
    }

    private long updateFolderData(Object actionTypeId, int folderId, int accusedRequired,
                                  oracle.jbo.domain.Date dateFrom, oracle.jbo.domain.Date dateTo, Object feesType,
                                  Object procId) {
        ViewObject excFolderDataView = getExcFolderDataView1();
        excFolderDataView.setWhereClause("ID = " + folderId);
        excFolderDataView.executeQuery();
        Row excFolderDataRow = excFolderDataView.first();
        System.out.println("update folder data id =" + folderId + " actionTypeId = " + actionTypeId +
                           " accusedRequired = " + accusedRequired);
        
        if (invals(actionTypeId,    37))
            excFolderDataRow.setAttribute("IsActive", "E");
        
        if (invals(actionTypeId, 28, 5,  11, 12, 13, 16, 30)) {  // ,10
            System.out.println("1111");
            excFolderDataRow.setAttribute("ExecutionFlag", 2);
        } else if (invals(actionTypeId, 31)) { // tasdek procedure
            System.out.println("22222");
            excFolderDataRow.setAttribute("ExecutionFlag", 1);
        } else if (invals(actionTypeId, 32, 36, 15, 22, 51, 10, 16, 43 , 15)) {
            System.out.println("36---------------------"); // cancel procedure
            excFolderDataRow.setAttribute("ExecutionFlag", 2);
            excFolderDataRow.setAttribute("IsActive", "N");
            if (invals(actionTypeId,   10,  43 , 15))
                excFolderDataRow.setAttribute("IsActive", "P");
            
        } else if (invals(actionTypeId, 33)) { // Edit procedure
            System.out.println("3333");
            Row r = getActionsRVO1().getCurrentRow();
            System.err.println(">> r.getAttribute(\"FolderGharama\") " + r.getAttribute("FolderGharama"));
            if ("N".equalsIgnoreCase(r.getAttribute("FolderGharama") + "")) {
                excFolderDataRow.setAttribute("EditProc", procId);
                excFolderDataRow.setAttribute("ExecutionFlag", 2);
                excFolderDataRow.setAttribute("IsActive", "N");
            } else {
                System.out.println("4444");
                excFolderDataRow.setAttribute("JudgmentText", r.getAttribute("JudgmentContent"));
            }
            /** Added By M.Salah - Update Integration Moi Execution Flag **/
        } else if (invals(actionTypeId, 1, 2, 8) && excFolderDataRow.getAttribute("ExecutionMoiFlag") != null &&
                   ((BigDecimal) excFolderDataRow.getAttribute("ExecutionMoiFlag")).intValue() == 1) {
            System.out.println("5555");
            //            excFolderDataRow.setAttribute("ExecutionMoiFlag", 2);
            excFolderDataRow.setAttribute("ExecutionFlag", accusedRequired);
        } else if (!invals(actionTypeId, 15, 22)) {
            System.out.println("666");
            excFolderDataRow.setAttribute("ExecutionFlag", accusedRequired);
        }

        if (dateFrom != null && dateTo != null) {
            System.out.println("777");
            excFolderDataRow.setAttribute("ImprisonmentStartDate", dateFrom);
            excFolderDataRow.setAttribute("ImprisonmentEndDate", dateTo);
        }

        if (invals(actionTypeId, 7) && invals(feesType, 3)) {
            System.out.println("888");
            excFolderDataRow.setAttribute("ClaimIssueFlag", 2);
        }

        String bcdId =
            excFolderDataRow.getAttribute("BusinessCaseDetailId") == null ? "0" :
            excFolderDataRow.getAttribute("BusinessCaseDetailId").toString();

        return Long.parseLong(bcdId);
    }


