    protected void callStoredProcedure(String stmt, Object[] bindVars) {
        PreparedStatement st = null;
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            // 1. Create a JDBC PreparedStatement for
            st = db.createPreparedStatement("begin " + stmt + ";end;", 0);
            if (bindVars != null) {
                System.out.println("bindVars != null");
                // 2. Loop over values for the bind variables passed in, if any
                for (int z = 0; z < bindVars.length; z++) {
                    System.out.println("Loop");
                    // 3. Set the value of each bind variable in the statement
                    st.setObject(z + 1, bindVars[z]);
                }
            }
            System.out.println("Before");
            // 4. Execute the statement
            st.executeUpdate();
            System.out.println("after");
        } catch (SQLException e) {
            throw new JboException(e);
        } finally {
            if (st != null) {
                try {
                    // 5. Close the statement
                    st.close();

                } catch (SQLException e) {
                }
            }
        }
    }


    protected void callStoredProcedure2(String stmt, Object... bindVars) {
        PreparedStatement st = null;
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            // 1. Create a JDBC PreparedStatement for

            st = db.createPreparedStatement("begin " + stmt + ";end;", 0);
            if (bindVars != null) {
                // 2. Loop over values for the bind variables passed in, if any
                for (int z = 0; z < bindVars.length; z++) {
                    // 3. Set the value of each bind variable in the statement
                    st.setObject(z + 1, bindVars[z]);
                }
            }
            // 4. Execute the statement
            st.executeUpdate();
        } catch (SQLException e) {
            throw new JboException(e);
        } finally {
            if (st != null) {
                try {
                    // 5. Close the statement
                    st.close();

                } catch (SQLException e) {
                    e.printStackTrace();
                }
            }
        }
    }

    public String delDate(String conDate) {
        //    String myDate = "Tue Nov 18 00:00:00 GMT 2014";
        String year = "";
        String strMnth = conDate.substring(4, 7);
        if (conDate.substring(4, 7).equals("Jan"))
            strMnth = "01";
        else if (conDate.substring(4, 7).equals("Feb"))
            strMnth = "02";
        else if (conDate.substring(4, 7).equals("Mar"))
            strMnth = "03";
        else if (conDate.substring(4, 7).equals("Apr"))
            strMnth = "04";
        else if (conDate.substring(4, 7).equals("May"))
            strMnth = "05";
        else if (conDate.substring(4, 7).equals("Jun"))
            strMnth = "06";
        else if (conDate.substring(4, 7).equals("Jul"))
            strMnth = "07";
        else if (conDate.substring(4, 7).equals("Aug"))
            strMnth = "08";
        else if (conDate.substring(4, 7).equals("Sep"))
            strMnth = "09";
        else if (conDate.substring(4, 7).equals("Oct"))
            strMnth = "10";
        else if (conDate.substring(4, 7).equals("Nov"))
            strMnth = "11";
        else if (conDate.substring(4, 7).equals("Dec"))
            strMnth = "12";
        String day = conDate.substring(8, 10);
        year = conDate.substring(24, 28);
        if (year.length() < 4) {
            year = conDate.substring(25, 29);
        } else if (year.length() > 4) {
            year = conDate.substring(23, 27);
        }

        String date = day + "-" + strMnth + "-" + year;

        return date;
    }

    public static String dateConvert(String deliverydate) {
        String[] split = deliverydate.split("-");
        BigDecimal year = new BigDecimal(0);
        String dateAfterTerra = null;
        if (split.length > 1) {
            if (split[2].length() < 3) {
                System.err.println("split.length" + split[2].length());
                year = new BigDecimal(split[2]).add(new BigDecimal(2000));
            } else {
                System.err.println("split.length" + split[2].length());

                year = new BigDecimal(split[2]);
            }
            dateAfterTerra = split[0].concat("-" + split[1].concat("-" + year));

        }
        SimpleDateFormat sdf = new SimpleDateFormat("dd-MMM-yyyy");
        java.util.Date date = null;
        try {
            if (dateAfterTerra != null)
                date = sdf.parse(dateAfterTerra);
        } catch (ParseException e) {
            e.printStackTrace();
        }

        sdf = new SimpleDateFormat("yyyy-MM-dd");

        if (date != null)
            return sdf.format(date);
        else
            return null;
    }

