    public void updateGuaranteeAmount(int resPartyId, double grantee, int folderId) {
        System.err.println("---resPartyId = " + resPartyId);
        System.err.println("---folderId = " + folderId);
        ViewObject excFolderDataUpdate = getExcFolderDataView1();
        ViewObject excFolderData = getExcFolderDataRVO1();
        excFolderData.setWhereClause("ID in(" + folderId + ")");
        excFolderData.executeQuery();
        String newJudmentText = "";
        if (excFolderData.getEstimatedRowCount() > 0) {
            String judgmentText = excFolderData.first().getAttribute("JudgmentText") + "";
            String str[] = judgmentText.trim().split(" ");
            String kafala = "\u0643\u0641\u0627\u0644\u0629";
            int j = -1;
            if (judgmentText != null && judgmentText.length() > 0) {
                for (int i = 0; i < str.length; i++) {
                    if (str[i].equals(kafala)) {
                        j = i + 1;
                        newJudmentText += "\u0643\u0641\u0627\u0644\u0629" + " " + grantee + " ";
                    }
                    if (!str[i].equals(kafala) && i != j)
                        newJudmentText += str[i] + " ";
                }
            }
        }
        System.err.println("newJudmentText = " + newJudmentText);
        ViewObject courtBcChargesParties = getExcCourtBcChargesPartiesVO3();
        courtBcChargesParties.setWhereClause("RES_PARTY_ID in(" + resPartyId + ")");
        System.err.println("query courtBcChargesParties am ---> " + courtBcChargesParties.getQuery());
        System.err.println("query courtBcChargesParties row count am ---> " +
                           courtBcChargesParties.getEstimatedRowCount());
        Row first = courtBcChargesParties.first();
        String chargeDecisionId = null;
        if (first != null) {
            chargeDecisionId = first.getAttribute("ChargeDecisionId") + "";
        }
        System.err.println("chargeDecisionId = " + chargeDecisionId);
        if (chargeDecisionId != null) {
            String sql =
                "UPDATE EXC_COURT_BC_CHARGE_DECISIONS SET GURANTEE_AMOUNT = " + grantee + " WHERE ID = " +
                chargeDecisionId;
            String sql2 =
                "UPDATE COURT_BC_HEARING_RES_PARTIES SET GUARANTEE = " + grantee + " WHERE ID = " + resPartyId;
            //            String sql3 = "UPDATE EXC_FOLDER_DATA SET JUDGMENT_TEXT = '"+newJudmentText +"' WHERE ID = " + folderId;

            try {
                execDML(sql);
                execDML(sql2);
                excFolderDataUpdate.first().setAttribute("JudgmentText", newJudmentText);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }

