    /** Added by M.Salah **/
    public boolean checkBCDetailsKollyNumber(BigDecimal businessCaseId) {
        ViewObject bcDetailsVO = getBusinessCaseDetailsVO1().getViewObject();
        ViewCriteria vc = bcDetailsVO.getViewCriteriaManager().getViewCriteria("BCDetailsVC_KollyNumber");
        vc.resetCriteria();
        bcDetailsVO.ensureVariableManager().setVariableValue("BusinessCaseIdParam", businessCaseId);
        bcDetailsVO.applyViewCriteria(vc);
        bcDetailsVO.executeQuery();
        System.err.println("bcDetailsVO.getEstimatedRowCount() : " + bcDetailsVO.getEstimatedRowCount());
        if (bcDetailsVO.getEstimatedRowCount() > 0)
            return true;
        else
            return false;
    }


