    private long getBusinessCaseId(BigDecimal resPartyId) {
        long businessCaseId = 0;

        String sql = "SELECT COURT_BC_HEARING_RES_ID FROM COURT_BC_HEARING_RES_PARTIES WHERE ID = ?";

        PreparedStatement ps = null;
        ResultSet rs = null;


        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setBigDecimal(1, resPartyId);

            rs = ps.executeQuery();
            if (rs.next()) {
                sql = "SELECT BUSINESS_CASE_ID " + " FROM COURT_BC_HEARING_RESERVATION " + " WHERE ID = ? ";
                ps = db.createPreparedStatement(sql, 0);
                ps.setInt(1, rs.getInt(1));
                rs = ps.executeQuery();
                if (rs.next()) {
                    businessCaseId = rs.getLong(1);
                }
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return businessCaseId;
    }

  



