    public int countPrevDegree(long businessCaseId, int partyId) {
        int count = 0;

        String sql =
            "SELECT MAX(RES.ID) " +
            " FROM BUSINESS_CASE CAS , COURT_BC_HEARING_RESERVATION RES , COURT_BC_HEARING_RES_PARTIES PART " +
            " WHERE RES.BUSINESS_CASE_ID = CAS.ID " + " AND RES.ID = PART.COURT_BC_HEARING_RES_ID " +
            " AND CAS.ID = ? " + " AND PART.PARTY_ID = ? ";

        PreparedStatement ps = null;
        ResultSet rs = null;

        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setLong(1, businessCaseId);
            ps.setInt(2, partyId);

            rs = ps.executeQuery();
            if (rs.next()) {
                int max = rs.getInt(1);

                sql =
                    "SELECT RES.CIRCLE_HEARING_DATE_ID " + " FROM COURT_BC_HEARING_RESERVATION RES " +
                    " WHERE RES.ID = ? ";
                ps = db.createPreparedStatement(sql, 0);
                ps.setInt(1, max);
                rs = ps.executeQuery();
                if (rs.next()) {
                    sql =
                        "SELECT DATES.BC_DEGREE_ID " + " FROM COURT_CIRCLES_DATES_HEARING DATES " +
                        " WHERE DATES.ID = ? ";
                    ps = db.createPreparedStatement(sql, 0);
                    ps.setInt(1, rs.getInt(1));
                    rs = ps.executeQuery();
                    if (rs.next()) {
                        count = rs.getInt(1);
                    }
                }
            }
        } catch (Exception e) {
            // TODO: Add catch code
            e.printStackTrace();
        } finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return count;
    }


