    public String[] getBusinessCaseDetails(long businessCaseId, int degree) {
        String[] caseDetails = new String[7];

        String sql =
            "SELECT CAS.CASE_NUMBER || '/' || AUTH.PAR_YEAR || '/' || DEGREES.NAME || '/' || ENT.ENTITY_NAME AS BUSINESS_CASE_NUMBER , " +
            " TO_CHAR(DATES.HEARING_DATE , 'yyyy-mm-dd') AS HEARING_DATE , DEGREES.NAME AS DEGREES_NAME , CAS.BUSINESS_CASE_NAME , AUTH.BUSINESS_CASE_ID , " +
            " DATES.ID AS DATES_ID , RES.ID AS RESERVATION_ID " +
            " FROM COURT_BC_HEARING_RES_PARTIES HEARING , COURT_BC_HEARING_RESERVATION RES , BUSINESS_CASE CAS , PAR_POLICE_AUTHORITY_REPORT AUTH , " +
            " COURT_CIRCLES_DATES_HEARING DATES , BUSINESS_CASE_DEGREES DEGREES , ENTITY ENT " +
            " WHERE AUTH.BUSINESS_CASE_ID = ? " + " AND HEARING.COURT_BC_HEARING_RES_ID = RES.ID " +
            " AND RES.BUSINESS_CASE_ID = CAS.ID " + " AND CAS.ID = AUTH.BUSINESS_CASE_ID " +
            " AND RES.CIRCLE_HEARING_DATE_ID = DATES.ID " + " AND DATES.BC_DEGREE_ID = DEGREES.ID " +
            " AND AUTH.ENTITY_ID = ENT.ID " + " AND DATES.BC_DEGREE_ID = ? ";

        PreparedStatement ps = null;
        ResultSet rs = null;

        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setLong(1, businessCaseId);
            ps.setInt(2, degree);

            rs = ps.executeQuery();

            if (rs.next()) {
                caseDetails[0] = rs.getString("BUSINESS_CASE_NUMBER");
                caseDetails[1] = rs.getString("HEARING_DATE");
                caseDetails[2] = rs.getString("DEGREES_NAME");
                caseDetails[3] = rs.getString("BUSINESS_CASE_NAME");
                caseDetails[4] = rs.getString("BUSINESS_CASE_ID");
                caseDetails[5] = rs.getString("DATES_ID");
                caseDetails[6] = rs.getString("RESERVATION_ID");
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        return caseDetails;
    }


