    public int lastProcedureAction(int folerId, int actionTypeId) {
        int action = 0;

        String sql =
            "SELECT MAX(PROC.ID) " +
            " FROM EXC_FOLDER_DATA FOLDER , EXC_FOLDER_ACTIONS ACTS , EXC_FOLDER_PROCEDURES PROC " +
            " WHERE FOLDER.ID = ACTS.FOLDER_RECORD_ID " +
            " AND ACTS.PROCEDURE_ID = PROC.ID  AND ACTS.DELETED_FLAG = 'N' " + " AND FOLDER.ID = ?";
        PreparedStatement ps = null;
        ResultSet rs = null;
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setInt(1, folerId);

            rs = ps.executeQuery();
            if (rs.next()) {
                int max = rs.getInt(1);
                if (max > 0) {
                    sql =
                        "SELECT ACTS.ACTION_TYPE " + " FROM EXC_FOLDER_ACTIONS ACTS " + " WHERE ACTS.PROCEDURE_ID = ? ";
                    ps = db.createPreparedStatement(sql, 0);
                    ps.setInt(1, max);
                    rs = ps.executeQuery();
                    if (rs.next()) {
                        action = rs.getInt(1);
                    }
                }
            }

        } catch (Exception e) {
            // TODO: Add catch code
            e.printStackTrace();
        } finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        return action;
    }


