    /**M.Salah**/
    public String getGozeyFromKoly(BigDecimal caseNumber, BigDecimal caseYear, BigDecimal businessCaseId,
                                   BigDecimal entityKolya) {
        CallableStatement cs = null;
        String result = null;
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            cs = db.createCallableStatement("begin ? := GET_GOZEY_FROM_KOLY(?, ?, ?, ?); end;", 0);
            cs.registerOutParameter(1, Types.VARCHAR);
            cs.setBigDecimal(2, caseNumber);
            cs.setBigDecimal(3, caseYear);
            cs.setBigDecimal(4, businessCaseId);
            cs.setBigDecimal(5, entityKolya);
            cs.execute();
            result = cs.getString(1);
            System.err.println("result gozeya number AM : " + result);
        } catch (SQLException sqle) {
            sqle.printStackTrace();
        } finally {
            try {
                cs.close();

            } catch (SQLException e) {
                e.printStackTrace();
            }
        }
        return result;
    }

    public String numberToText(BigDecimal amount) {
        CallableStatement cs = null;
        String result = null;
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            cs = db.createCallableStatement("begin ? := NUMBER_TO_TEXT(?); end;", 0);
            cs.registerOutParameter(1, Types.VARCHAR);
            cs.setBigDecimal(2, amount);
            cs.execute();
            result = cs.getString(1);
            System.err.println("result AM : " + result);
        } catch (SQLException sqle) {
            sqle.printStackTrace();
        } finally {
            try {
                cs.close();

            } catch (SQLException e) {
                e.printStackTrace();
            }
        }
        return result;
    }

