    public boolean checkProClaimExist(String claimId) {
        ViewObject searchClaimResultView = getExcProcedureClaimVO1();
        //ADFUtil.findIterator("ExcProcedureClaimVO1Iterator").getViewObject();
        ViewCriteria vc = searchClaimResultView.getViewCriteriaManager().getViewCriteria("CheckProClaimExistsVC");
        vc.resetCriteria();
        searchClaimResultView.ensureVariableManager().setVariableValue("claimIdParam", claimId);
        searchClaimResultView.applyViewCriteria(vc);
        searchClaimResultView.executeQuery();
        if (searchClaimResultView.getEstimatedRowCount() > 0)
            return true;
        else
            return false;

    }

    public void insertClaimProcedureLog(oracle.jbo.domain.Number claimId, String claimNumber, BigDecimal claimYear,
                                        String claimRepeatedFlag, BigDecimal claimTypeId, BigDecimal claimEntityColya,
                                        BigDecimal claimEntityPartial, BigDecimal claimEntityPolice,
                                        oracle.jbo.domain.Number procedureId, String procedureNumber,
                                        BigDecimal procedureTypeId, Timestamp procedureDate,
                                        BigDecimal loggedInEntityId) {
        ViewObject claimProcedureLogVO = this.getExcProcedureClaimLog1();
        Row claimProcedureLogRow = claimProcedureLogVO.createRow();
        claimProcedureLogRow.setAttribute("ClaimId", claimId);
        claimProcedureLogRow.setAttribute("ClaimNumber", claimNumber);
        claimProcedureLogRow.setAttribute("ClaimYear", claimYear);
        claimProcedureLogRow.setAttribute("ClaimRepeatedFlag", claimRepeatedFlag);
        claimProcedureLogRow.setAttribute("ClaimTypeId", claimTypeId);
        claimProcedureLogRow.setAttribute("ClaimEntityColya", claimEntityColya);
        claimProcedureLogRow.setAttribute("ClaimEntityPartial", claimEntityPartial);
        claimProcedureLogRow.setAttribute("ClaimEntityPolice", claimEntityPolice);
        claimProcedureLogRow.setAttribute("ProcedureId", procedureId);
        claimProcedureLogRow.setAttribute("ProcedureNumber", procedureNumber);
        claimProcedureLogRow.setAttribute("ProcedureTypeId", procedureTypeId);
        claimProcedureLogRow.setAttribute("ProcedureDate", procedureDate);
        claimProcedureLogRow.setAttribute("LoggedInEntityId", loggedInEntityId);
        claimProcedureLogVO.insertRow(claimProcedureLogRow);
        getDBTransaction().commit();
    }

