    public BigDecimal insertLawyer(BigDecimal parId, String nid, BigDecimal registerationId, String name,
                                   String comments, String retainerNumber, String phoneNumber,String createdBy) {
        
        System.err.println("insertLawyer==========================================");
        BigDecimal id = new BigDecimal(0);
        
        ViewObject vo = this.getParLawyersVO1();

        Row rw = vo.createRow();
        rw.setAttribute("ParId", parId);
        rw.setAttribute("Name", name);
        rw.setAttribute("RetainerNumber", retainerNumber);
        rw.setAttribute("PhoneNumber", phoneNumber);
        rw.setAttribute("CreatedBy", createdBy);
        rw.setAttribute("Registration1", registerationId);
        rw.setAttribute("Nid", nid);
        if (comments != null)
            rw.setAttribute("Comments", comments);
        vo.insertRow(rw);
        this.getDBTransaction().commit();
        System.out.println("vo.getCurrentRow().getAttribute(\"Id\")   ------------" +
                           vo.getCurrentRow().getAttribute("Id"));
        id = new BigDecimal(vo.getCurrentRow().getAttribute("Id") + "");
        return id;
    }
