    public ArrayList<Integer> getProsecutionUnderKolyea(int kolyeaId) {
        ArrayList<Integer> entitiesIds = new ArrayList<Integer>();

        String sql = "SELECT ENT.ID FROM ENTITY ENT " + " WHERE ENT.PARENT_ENTITY_ID = ? ";
        PreparedStatement ps = null;
        ResultSet rs = null;
        System.out.println(sql + "---" + kolyeaId);
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setInt(1, kolyeaId);

            rs = ps.executeQuery();

            while (rs.next()) {
                entitiesIds.add(rs.getInt(1));
            }

        } catch (Exception e) {
            // TODO: Add catch code
            e.printStackTrace();
        }

        finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        return entitiesIds;
    }

