    public int checkDatesHearing(long businessCaseId, long id) {
        int count = 0;
        String sql =
            "SELECT MAX(RES.ID) " + "FROM COURT_BC_HEARING_RESERVATION RES " + "WHERE RES.CIRCLE_HEARING_DATE_ID = ? " +
            "AND RES.BUSINESS_CASE_ID = ? ";
        PreparedStatement ps = null;
        ResultSet rs = null;
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setLong(1, id);
            ps.setLong(2, businessCaseId);
            rs = ps.executeQuery();
            if (rs.next()) {
                count = rs.getInt(1);
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        return count;
    }

    public BigDecimal getLedgerId(BigDecimal entityKolayaId) {
        BigDecimal ledgerId = new BigDecimal(0);

        String sql =
            "select el.id from entity_ledger el , ledger_schema ls where el.entity_id = ? and el.id =LS.ENTITY_LEDGER_ID and LS.CASE_SCHEMA_ID = 3643";
        System.out.println(entityKolayaId + "sql   " + sql);
        PreparedStatement ps = null;
        ResultSet rs = null;
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setBigDecimal(1, entityKolayaId);
            rs = ps.executeQuery();
            if (rs.next()) {
                ledgerId = rs.getBigDecimal(1);
            }

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return ledgerId;
    }

    public String getDatesHearing(BigDecimal id) {
        String hearingDate = "";

        String sql =
            "SELECT TO_CHAR(HEAR.HEARING_DATE , 'yyyy') " + " FROM COURT_CIRCLES_DATES_HEARING HEAR " +
            " WHERE HEAR.ID = ? ";
        PreparedStatement ps = null;
        ResultSet rs = null;
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setBigDecimal(1, id);
            rs = ps.executeQuery();
            if (rs.next()) {
                hearingDate = rs.getString(1);
            }

        } catch (Exception e) {
            e.printStackTrace();
        }

        finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return hearingDate;
    }

