    public void updateCriminalJusticeFiles(long id, String documentId) {
        String sql = "UPDATE CRIMINAL_JUSTICE_FILES_DETAILS SET DID = ? WHERE ID = ? ";

        PreparedStatement ps = this.getDBTransaction().createPreparedStatement(sql, 0);
        try {
            ps.setString(1, documentId);
            ps.setLong(2, id);
            ps.executeUpdate();
            this.getDBTransaction().commit();
            ps.close();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

