    public String[] getExPenalty(BigDecimal partyId) {
        String[] data = new String[10];

        PreparedStatement ps = null;
        ResultSet rs = null;

        DBTransaction db = null;
        try {
            db = this.getDBTransaction();


            String sql =
                "select NVL (IMPRISONMENT_DAYS ,0) , NVL (IMPRISONMENT_MONTHS ,0), NVL (IMPRISONMENT_YEARS,0) , NVL (GURANTEE_AMOUNT ,0) , NVL (PENALTY_AMOUNT,0) , " +
                "NVL (WORK_AMOUNT,0) ,NVL (UN_DEFINEED_PENALTY,0) , HARD_LABOUR_FLAG , FOREVER_FLAG ,EXECUTION_FLAG " +
                "from EXC_COURT_BC_CHARGE_DECISIONS where id in " +
                "(select max( CHARGE_DECISION_ID )from EXC_COURT_BC_CHARGES_PARTIES where RES_PARTY_ID in " +
                "(select max(id ) from COURT_BC_HEARING_RES_PARTIES where PARTY_ID = ? ))";

            ps = db.createPreparedStatement(sql, 0);
            ps.setLong(1, partyId.longValue());
            rs = ps.executeQuery();
            System.err.println(sql + "---" + partyId);
            if (rs.next()) {
                System.out.println("Found Data");
                data[0] = rs.getString(1);
                data[1] = rs.getString(2);
                data[2] = rs.getString(3);
                data[3] = rs.getString(4);
                data[4] = rs.getString(5);
                data[5] = rs.getString(6);
                data[6] = rs.getString(7);
                data[7] = rs.getString(8);
                data[8] = rs.getString(9);
                data[9] = rs.getString(10);
            }

            rs.close();
            ps.close();
        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            try {
                rs.close();
                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return data;
    }


    public Map<BigDecimal, String> gethearingDates(BigDecimal degree, BigDecimal bcID) {
        Map<BigDecimal, String> mapDates = new HashMap<BigDecimal, String>();
        PreparedStatement stat = null;
        ResultSet rs = null;
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd");
                       Date date1 = sdf.parse("2025-11-01");
            Date date2 = new Date();
            String sql =
                "SELECT distinct CO.ID , TO_CHAR(CO.HEARING_DATE , 'yyyy-mm-dd')     as HEARING_DATE   FROM COURT_CIRCLES_DATES_HEARING CO   , COURT_BC_HEARING_RESERVATION RES ,   COURT_BC_HEARING_RES_PARTIES PART ,BUSINESS_CASE_DEGREES deg  " +
                "WHERE RES.IS_ACTIVE = 'Y' and RES.CIRCLE_HEARING_DATE_ID = CO.ID   and CO.BC_DEGREE_ID = deg.id  " +
                "AND RES.ID = PART.COURT_BC_HEARING_RES_ID  AND PART.POSTPONED = 0  " +
                "AND  PART.UNSPECIALIZED_FLAG = 0   and PART.attendance is  null  and RES.PROSECUTION_JUDEGEMENT_FLAG in( 1 , 0) " +
                "and CO.HEARING_DATE <= sysdate and PART.BC_DEGREE_SPEC_ID = " + degree 
           
              // + "and ( 30   >= sysdate - CO.HEARING_DATE  and  co.HEARING_DATE   >=  TO_DATE('2025-02-01' , 'yyyy-mm-dd'))" 
              +  " and  PART.DELETED_FLAG ='N' and    RES.BUSINESS_CASE_ID=" + bcID + " ORDER BY HEARING_DATE";
           if(date2.after(date1))
         //  if (true)
           {
                sql =
                                "SELECT distinct CO.ID , TO_CHAR(CO.HEARING_DATE , 'yyyy-mm-dd')     as HEARING_DATE   FROM COURT_CIRCLES_DATES_HEARING CO   , COURT_BC_HEARING_RESERVATION RES ,   COURT_BC_HEARING_RES_PARTIES PART ,BUSINESS_CASE_DEGREES deg  " +
                                "WHERE RES.IS_ACTIVE = 'Y' and RES.CIRCLE_HEARING_DATE_ID = CO.ID   and CO.BC_DEGREE_ID = deg.id  " +
                                "AND RES.ID = PART.COURT_BC_HEARING_RES_ID  AND PART.POSTPONED = 0  " +
                                " AND  PART.UNSPECIALIZED_FLAG = 0   and PART.attendance is  null  and RES.PROSECUTION_JUDEGEMENT_FLAG in( 1 , 0) " +
                                "and CO.HEARING_DATE <= sysdate and PART.BC_DEGREE_SPEC_ID = " + degree 
                           
                               + "and (   TO_DATE(sysdate , 'dd-mm-rrrr') - ( TO_DATE(CO.HEARING_DATE , 'dd-mm-rrrr')) < 8 or RES.ACTIVE_CIRCLE_DATE = 1   or   TO_DATE(CO.HEARING_DATE , 'dd-mm-rrrr') < TO_DATE( '01-11-2025' , 'dd-mm-rrrr') )" 
                              +  " and  PART.DELETED_FLAG ='N' and    RES.BUSINESS_CASE_ID=" + bcID + " ORDER BY HEARING_DATE";
           
            }
            stat = db.createPreparedStatement(sql, 1);

            rs = stat.executeQuery();
            System.err.println(sql + "---" + sql);
            while (rs.next()) {

                System.err.println("%%sql%%");

                mapDates.put(new BigDecimal(rs.getString(1)), rs.getString(2));
            }


        } catch (SQLException e) {
            e.printStackTrace();
        } catch (ParseException e) {
        }

        finally {
            try {
                rs.close();
                stat.close();

            } catch (Exception e) {
                e.printStackTrace();
            }
        }


        return mapDates;
    }

