    public void updateProsecutorFolderData(BigDecimal folderId , String confirmation) {
        System.err.println(folderId+" -------------updateProsecutorFolderData---------------------------"+confirmation);
       
        ViewObject vo = this.filterByViewCriteria("ExcFolderData1", "Id", "" + folderId);
        RowSetIterator rws = vo.createRowSetIterator(null);
        while (rws.hasNext()) {
            System.out.println("Previous Folder Data");
            Row row = rws.next();
             {
                row.setAttribute("IsActive", confirmation );
                System.out.println("UPDATEd  FOLDER DATA ");
            }
            this.getDBTransaction().commit();
        }
    }
    
    
    

    public void updatePreviousFolderData(BigDecimal partyId) {
        System.err.println("ENTITY ----------------------------------------");
        BigDecimal resPartyId = updateFolderDataFlag(partyId);
        System.out.println("Previos Res Party Id Is :" + resPartyId);
        ViewObject vo = this.filterByViewCriteria("ExcFolderData1VO1", "ResPartyId", "" + resPartyId);
        RowSetIterator rws = vo.createRowSetIterator(null);
        while (rws.hasNext()) {
            System.out.println("Previous Folder Data");
            Row row = rws.next();
            BigDecimal flag = (BigDecimal) row.getAttribute("ExecutionMoiFlag");
            if (flag.compareTo(new BigDecimal(1)) == 0) {
                row.setAttribute("ExecutionMoiFlag", new BigDecimal(3));
                System.out.println("UPDATEd  FOLDER DATA ");
            }
        }
    }


