    public BigDecimal getDependentNewSeq(BigDecimal year, BigDecimal entityID, BigDecimal dependentOrderType) {
        BigDecimal dependentNewSeq = new BigDecimal(1);
        GenericVOImpl bcChrgDepOrdROVO = getExcCourtBcChrgDepOrdROVO();

        System.out.println(" year : " + year);
        System.out.println(" entityID : " + entityID);
        System.out.println(" dependentOrderType : " + dependentOrderType);

        bcChrgDepOrdROVO.setWhereClause("YEAR = " + year + " AND ENTITY_ID = " + entityID +
                                        " AND DEPENDENT_ORDER_TYPE = " + dependentOrderType +
                                        " AND SEQUENCE_NUMBER > 0");
        bcChrgDepOrdROVO.executeQuery();
        if (null != bcChrgDepOrdROVO && bcChrgDepOrdROVO.getEstimatedRowCount() > 0) {
            ExcCourtBcChrgDepOrdROVORowImpl last = (ExcCourtBcChrgDepOrdROVORowImpl) bcChrgDepOrdROVO.last();
            System.out.println("AM last.getSequenceNumber() : " + last.getSequenceNumber());
            dependentNewSeq = last.getSequenceNumber().add(dependentNewSeq);
            //            return dependentNewSeq;
        }
        System.out.println("AM dependentNewSeq : " + dependentNewSeq);
        bcChrgDepOrdROVO.setWhereClause("ID >= 0");
        bcChrgDepOrdROVO.executeQuery();
        return dependentNewSeq;
    }

