    public void updateExcFolderActions(BigDecimal procedureId,String isActive ) {
        
        System.err.println("updateExcFolderActions_procedureId =" +procedureId);
        System.err.println("updateExcFolderActions_isActive =" +isActive);
        String  deleteFlag = "Y";
        String sql = "UPDATE EXC_FOLDER_ACTIONS SET IS_ACTIVE = '"+isActive+"' WHERE PROCEDURE_ID = " +procedureId ;
        String sqlSetSysDate = "UPDATE EXC_FOLDER_ACTIONS SET EXP_APPROVAL_DATE = SYSDATE WHERE PROCEDURE_ID = " +procedureId ;
        String sqlDeleteFlag = "UPDATE EXC_FOLDER_ACTIONS SET DELETED_FLAG = '"+deleteFlag+"' WHERE PROCEDURE_ID = " +procedureId ;
        if(null != isActive && isActive.equals("X")){
            try {
                execDML(sql);
                execDML(sqlSetSysDate);
                execDML(sqlDeleteFlag);
                this.getDBTransaction().commit();
            } catch (Exception e) {
                System.err.println("updateToPostponed___ExcFolderActions1" + e.getMessage());
            }
        }else{
            try {
                execDML(sql);
                execDML(sqlSetSysDate);
                this.getDBTransaction().commit();
            } catch (Exception e) {
                System.err.println("updateToPostponed___ExcFolderActions2" + e.getMessage());
            }
        }
    }
