    public BigDecimal  getStatusForBusinessCaseId(BigDecimal businessCaseId) {

        System.err.println("returnStatusForBusinessCaseIdAMImplJava");
//        String sql = "SELECT LKP_BUSINESS_CASE_STATUS.STATUS_ID,\n" + "LKP_CASE_SCHEMA_STATUS.CASE_SCHEMA_ID,\n" +
//                            "business_case_details.case_schema_id ehalaSchemaId,\n" +
//                            "TO_DATE(trunc(BUSINESS_CASE_DETAILS.CREATED_DATE), 'dd-mm-yyyy') detailDate,\n" +
//                            "BUSINESS_CASE_DETAILS.BUSINESS_CASE_ID\n" + "FROM LKP_BUSINESS_CASE_STATUS,\n" +
//                            "LKP_CASE_SCHEMA_STATUS,\n" + "BUSINESS_CASE_DETAILS\n" + "Where\n" +
//                            "LKP_CASE_SCHEMA_STATUS.CASE_SCHEMA_ID = BUSINESS_CASE_DETAILS.CASE_SCHEMA_ID\n" +
//                            "AND LKP_BUSINESS_CASE_STATUS.STATUS_ID = LKP_CASE_SCHEMA_STATUS.STATUS\n" +
//                            "AND BUSINESS_CASE_DETAILS.BUSINESS_CASE_ID = " + businessCaseId + "\n" +
//                            "order by BUSINESS_CASE_DETAILS.CREATED_DATE desc,BUSINESS_CASE_DETAILS.id";
            
            String sql ="SELECT STATUS_ID  FROM (SELECT LKP_BUSINESS_CASE_STATUS.STATUS_ID,\n" + 
            "         LKP_CASE_SCHEMA_STATUS.CASE_SCHEMA_ID,\n" + 
            "         business_case_details.case_schema_id ehalaSchemaId,\n" + 
            "         TO_DATE (TRUNC (BUSINESS_CASE_DETAILS.CREATED_DATE), 'dd-mm-yyyy')\n" + 
            "            detailDate,\n" + 
            "         BUSINESS_CASE_DETAILS.BUSINESS_CASE_ID\n" + 
            "    FROM LKP_BUSINESS_CASE_STATUS,\n" + 
            "         LKP_CASE_SCHEMA_STATUS,\n" + 
            "         BUSINESS_CASE_DETAILS\n" + 
            "   WHERE     LKP_CASE_SCHEMA_STATUS.CASE_SCHEMA_ID =\n" + 
            "                BUSINESS_CASE_DETAILS.CASE_SCHEMA_ID\n" + 
            "         AND LKP_BUSINESS_CASE_STATUS.STATUS_ID = LKP_CASE_SCHEMA_STATUS.STATUS\n" + 
            "         AND BUSINESS_CASE_DETAILS.BUSINESS_CASE_ID = " + businessCaseId + "\n" + 
            "ORDER BY BUSINESS_CASE_DETAILS.CREATED_DATE DESC, BUSINESS_CASE_DETAILS.id)\n" + 
            "WHERE ROWNUM = 1";

        Object statusForBusinessCaseId = getDataAsObjectFromQuery(sql);
        if (statusForBusinessCaseId == null)
            return new BigDecimal(0);

        System.err.println("statusForBusinessCaseId =" + statusForBusinessCaseId);
        return new BigDecimal(statusForBusinessCaseId.toString());
    }

