    /** Added by MoSalah **/
    public void insertSearchScreenLog(BigDecimal screenId,String screenName,BigDecimal entityId,BigDecimal CaseTypeId, String CaseYear, BigDecimal CaseNumber, BigDecimal userId) {
        System.err.println("public void insertSearchScreenLog");
        String sql =
            "insert into EXC_Search_Screen_LOG(Screen_ID, Screen_NAME, ENTITY_ID, CAS_TYPE_ID, CASE_YEAR, CASE_NUMBER, USER_ID ) values(?, ?, ?, ?, ?, ?,?)";
        PreparedStatement ps = null;
        DBTransaction db = null;
        try {
            db = this.getDBTransaction();
            ps = db.createPreparedStatement(sql, 0);
            ps.setBigDecimal(1, screenId);
            ps.setString(2, screenName);
            ps.setBigDecimal(3, entityId);
            ps.setBigDecimal(4, CaseTypeId);
            ps.setString(5, CaseYear);
            ps.setBigDecimal(6, CaseNumber);
            ps.setBigDecimal(7, userId);
            
            ps.executeUpdate();
            getDBTransaction().commit();
            ps.close();
        } catch (Exception e) {
            e.printStackTrace();
            System.err.println("Message = " + e.getMessage());
            throw new oracle.jbo.JboException(e);
        } finally {
            try {

                ps.close();

            } catch (Exception e) {
                e.printStackTrace();
                System.err.println("Message = " + e.getMessage());
                throw new oracle.jbo.JboException(e);
            }
        }
    }

